package com.deardiary.privateapp;
import android.app.*;import android.view.*;import android.graphics.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.json.*;import java.io.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class)@Config(sdk=28,manifest=Config.NONE)@GraphicsMode(GraphicsMode.Mode.NATIVE)
public class UpdateSheetTest{
 @Test public void unavailableTimestampAndFailureStayHonest()throws Exception{Activity a=Robolectric.buildActivity(Activity.class).setup().get();UpdateSheet v=new UpdateSheet(a,false,new JSONObject().put("failed",true),"2.14",0,false,()->{},()->{});assertEquals("Check again",v.update.getText().toString());assertTrue(v.status.getText().toString().contains("Could not check"));v.downloading(50);assertFalse(v.update.isEnabled());assertEquals(50,v.progress.getProgress());}
 @Test public void renderBothStates()throws Exception{Activity a=Robolectric.buildActivity(Activity.class).setup().get();for(boolean available:new boolean[]{false,true})for(boolean dark:new boolean[]{false,true}){JSONObject r=new JSONObject().put("version","2.15").put("notes","A softer update screen\nCurrent and next versions, clear release notes, and Update or Later.\n\nKnow where you are\nSee the installed version and the time of the last app update on this device.");boolean[] tapped={false},closed={false};UpdateSheet v=new UpdateSheet(a,dark,r,available?"2.14":"2.15",1795800141000L,available,()->tapped[0]=true,()->closed[0]=true);assertEquals(available?"Update to 2.15":"Check again",v.update.getText().toString());assertEquals(available?"Later":"Close",v.later.getText().toString());v.update.performClick();assertTrue(tapped[0]);v.later.performClick();assertTrue(closed[0]);int w=390,h=710;v.measure(View.MeasureSpec.makeMeasureSpec(w,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(h,View.MeasureSpec.EXACTLY));v.layout(0,0,w,h);Bitmap bitmap=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);v.draw(new Canvas(bitmap));File f=new File("/downloads/update-ui-preview/"+(available?"available":"latest")+(dark?"-dark":"")+".png");f.getParentFile().mkdirs();try(FileOutputStream out=new FileOutputStream(f)){bitmap.compress(Bitmap.CompressFormat.PNG,100,out);}}}
}
